// .NET's guidance: prefer a generic method over a non-generic one, so the
// JIT specialises (and inlines) it at the call site with concrete types.
static T ClampAdd<T>(T a, T b, T limit) where T : IComparable<T> {
    var s = a + b;
    return s > limit ? limit : s;
}

// legacy hint for a genuinely hot small method:
[MethodImpl(MethodImplOptions.AggressiveInlining)]
static int Step(int x) => x < 0 ? 0 : x;

